// Imports
const { DynamoDBClient } = require("@aws-sdk/client-dynamodb");
const { DynamoDBDocumentClient, GetCommand, QueryCommand, PutCommand, UpdateCommand } = require("@aws-sdk/lib-dynamodb");
const dynamoDbDocumentClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));
const ULID = require('ulid');
const dynamoBatchOps = require("dynamodb/dynamo-batch-ops/index");
const env = require('environment/index');
const Module = require("node:module");
const DEFAULT_TABLE_NAME = process.env.TABLE_NAME;

////////////////////////////////////////
// Register a new user.
////////////////////////////////////////
async function registerUser(firstName, lastName, email, cognitoId, userSocialProviderName, userSocialProviderType, userSocialProviderUserId, tableName = DEFAULT_TABLE_NAME) {
    try {
        // Peek user via email
        let userCognitoData = await peekUserByEmail(email, tableName);
        if (userCognitoData.length > 0) {
            let duplicateRegistration = false;
            for (let userCognito of userCognitoData) {
                if (userCognito["sk"].split("#")[2].valueOf() == cognitoId.valueOf()) {
                    duplicateRegistration = true;
                    break;
                }
            }

            // User registered via federation or other cognito source with same email
            if (!duplicateRegistration) {
                // Record cognito id in the user's profile
                const command = new PutCommand({
                    TableName: tableName,
                    Item: {
                        "pk": env.DYNAMO_ENTITY_USER + "#" + userCognitoData[0]["pk"].split("#")[1],
                        "sk": env.DYNAMO_ENTITY_PROFILE + "#" + env.DYNAMO_ENTITY_COGNITO_DATA
                            + "#" + cognitoId,
                        "userSocialProviderName": userSocialProviderName,
                        "userSocialProviderType": userSocialProviderType,
                        "userSocialProviderUserId": userSocialProviderUserId,
                        "userEmail": email,
                        "userCognitoId": cognitoId,
                        "userDeactivated": false,
                    }
                });
                await dynamoDbDocumentClient.send(command);
            }
            else {
                throw "User already registered";
            }
        }

        else {
            // New user
            const userUUID = ULID.ulid();
            const createdAt = Date.now();

            // Write batch
            await dynamoBatchOps.dynamoWriteManyItems(tableName, [
                // User info
                {
                    PutRequest: {
                        Item: {
                            "pk": env.DYNAMO_ENTITY_USER + "#" + userUUID,
                            "sk": env.DYNAMO_ENTITY_PROFILE + "#" + env.DYNAMO_ENTITY_INFO,
                            "userPlan": env.PLAN_TYPE_FREE,
                            "userEmailAddress": email,
                            "userAvatarUri": "",
                            "userFirstName": firstName,
                            "userLastName": lastName,
                            "userPreferredLocale": env.LOCALE_EN,
                            "isProfileComplete": false,
                            "userCreatedAt": createdAt,
                        }
                    }
                },
                // User cognito ids
                {
                    PutRequest: {
                        Item: {
                            "pk": env.DYNAMO_ENTITY_USER + "#" + userUUID,
                            "sk": env.DYNAMO_ENTITY_PROFILE + "#" + env.DYNAMO_ENTITY_COGNITO_DATA + "#" + cognitoId,
                            "userSocialProviderName": userSocialProviderName,
                            "userSocialProviderType": userSocialProviderType,
                            "userSocialProviderUserId": userSocialProviderUserId,
                            "userEmail": email,
                            "userCognitoId": cognitoId,
                            "userDeactivated": false,
                        }
                    }
                },
                // User notification settings
                {
                    PutRequest: {
                        Item: {
                            "pk": env.DYNAMO_ENTITY_USER + "#" + userUUID,
                            "sk": env.DYNAMO_ENTITY_PROFILE + "#" + env.DYNAMO_ENTITY_NOTIFICATION_SETTINGS,
                            "userFcmToken": "",
                        }
                    }
                },
            ]);
        }
    } catch (e) {
        console.error("In registerUser", e);
        throw e;
    }
}

////////////////////////////////////////
// Fetch user email
////////////////////////////////////////
async function peekUserByEmail(email, tableName = DEFAULT_TABLE_NAME) {
    try {
        const command = new QueryCommand({
            TableName: tableName,
            IndexName: env.INDEX_NAME_USER_EMAIL_GSI,
            KeyConditionExpression: '#userEmail = :userEmail',
            ExpressionAttributeNames: {
                "#userEmail": "userEmail",
            },
            ExpressionAttributeValues: {
                ":userEmail": email,
            }
        });
        const userDocArr = await dynamoDbDocumentClient.send(command);
        return userDocArr["Items"];
    } catch (e) {
        console.error("In peekUserByEmail", e);
        throw "Could not find user by email";
    }
}

module.exports = {
    registerUser,
    peekUserByEmail
}